      {linked.state.status === 'error' && (
        <Alert
          type="error"
          showIcon
          title="Failed to load linked channels"
          description={linked.state.error}
        />
      )}
      {all.state.status === 'ok' && linked.state.status === 'ok' && (
        <ChannelPickerBody
          // Remount when the linked set actually changes underneath us (render-
