          key={linked.state.data
            .map((c) => c.id)
            .sort()
            .join(',')}
          suiteId={suiteId}
          canManage={canManage}
          allChannels={all.state.data}
          initialLinked={linked.state.data}
          onResync={linked.reload}
        />
      )}
    </Card>
  );
}

