1	import { useCallback, useEffect, useState } from 'react';
2	
3	import { type FailureKind, fetchFailure } from '../utils/errors';
4	
5	/** Three-state result of an async fetch. */
6	export type AsyncState<T> =
7	  | { status: 'loading' }
8	  | { status: 'ok'; data: T }
9	  | {
10	      status: 'error';
11	      error: string;
12	      kind: FailureKind;
13	      httpStatus?: number;
14	      requestId?: string;
15	    };
16	
17	/**
18	 * Fetch on mount (and on `reload()`), with a cancelled-guard so a late resolution after unmount
19	 * doesn't set state, and rejection normalised to a string `error`.
20	 */
21	export function useAsyncData<T>(fetcher: (signal: AbortSignal) => Promise<T>): {
22	  state: AsyncState<T>;
23	  reload: () => void;
24	} {
25	  const [state, setState] = useState<AsyncState<T>>({ status: 'loading' });
26	  const [nonce, setNonce] = useState(0);
27	
28	  useEffect(() => {
29	    let cancelled = false;
30	    const controller = new AbortController();
31	    fetcher(controller.signal)
32	      .then((data) => {
33	        if (!cancelled) setState({ status: 'ok', data });
34	      })
35	      .catch((err: unknown) => {
36	        if (!cancelled) {
37	          const failure = fetchFailure(err, String(err));
38	          setState({
39	            status: 'error',
40	            error: failure.message,
41	            kind: failure.kind,
42	            httpStatus: failure.status,
43	            requestId: failure.requestId,
44	          });
45	        }
46	      });
47	    return () => {
48	      cancelled = true;
49	      controller.abort();
50	    };
51	    // Re-run on mount and whenever `reload` bumps the nonce; the fetcher identity
52	    // is intentionally not a dependency.
53	    // eslint-disable-next-line react-hooks/exhaustive-deps
54	  }, [nonce]);
55	
56	  const reload = useCallback(() => setNonce((n) => n + 1), []);
57	  return { state, reload };
58	}
